contract InvMutTest {
    C c;
    bool firstReverted;
    bool secondReverted;

    constructor(C _c) {
        c = _c;
    }

    function test(uint val1, uint val2) public {
        (bool s1, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", val1));
        firstReverted = !s1;
        (bool s2, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", val2));
