pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newLog) public {
        vm.assume(newLog != address(0));

        // Initialize the contract
        c.Initialized();

        // Record the current LogFile
        address logBefore = address(c.LogFile());

        // Attempt to change LogFile after initialization
        bool ok;
        try c.SetLogFile(newLog) { ok = true; } catch { ok = false; }

        // The invariant: if initialized, SetLogFile must either revert or leave LogFile unchanged.
        // The correct contract always reverts (ok == false), thus LogFile never changes.
        // The buggy contract succeeds (ok == true) and changes LogFile, violating the rule.
        assertTrue(!ok || address(c.LogFile()) == logBefore);
    }
}

