pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newLog) public {
        vm.assume(newLog != address(0) && newLog != address(this));
        address initialLog = address(new Log());
        c.SetLogFile(initialLog);
        c.SetMinSum(0);
        c.Initialized();

        vm.prank(address(123456));
        c.SetLogFile(newLog);

        assertTrue(getLogFileAddress() == initialLog || getLogFileAddress() == newLog);
    }

    function getLogFileAddress() internal view returns (address) {
        (bool ok, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("LogFile()"));
        if (!ok) return address(0);
        return abi.decode(data, (address));
    }
}

contract Log {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;

    Message LastMsg;

    function AddMessage(address _adr,uint _val, string memory _data)
    public
    {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

