pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 lockTime, address logAddr) public {
        vm.assume(logAddr != address(0) && logAddr.code.length == 0);
        // Set initial LogFile to a non-zero EOA to avoid zero-address edge cases
        c.SetLogFile(address(this));
        c.Initialized();
        // Call SetLogFile with a new address that has no code (EOA); the bug ignores it
        c.SetLogFile(logAddr);
        // Reference contract's LogFile is still address(this) (since bug didn't change it),
        // so a subsequent Put call should not revert (address(this) has no Log code but is an EOA, low-level call succeeds).
        // However, the invariant we check is: having address(this) as LogFile does not revert on Put.
        // This tests the difference: if the buggy contract had actually changed LogFile to logAddr (another EOA),
        // Put would still not revert. The actual difference is that reference keeps old LogFile, bug ignores new one.
        // We need an adversarial helper: deploy a Log contract to be the old LogFile, then replace with an EOA.
        // If reference uses old Log (contract) -> works; if bug uses new (EOA) -> works too. This doesn't revert.
        // Instead: set initial LogFile to a contract, then SetLogFile to an EOA. Reference uses contract (succeeds),
        // bug ignores change and uses contract (succeeds). No difference.
        // Better: set initial LogFile to zero, Initialize, then SetLogFile to a contract. Reference uses contract (succeeds);
        // bug ignores and keeps zero. Call Put: reference calls zero address -> low-level call to zero address succeeds (empty fallback?).
        // Actually, call to zero address succeeds. So no revert.
        // The difference is about the state variable value, not revert. Check it via a getter.
        // LogFile is of type Log, which is a contract type. The auto-generated getter returns `Log` (address).
        // We can compare `address(c.LogFile())` before and after SetLogFile.
        // But the previous attempt "After initialization, calling SetLogFile must update the LogFile state variable; the bug leaves it unchanged." was already tried and presumably rejected.
        // Let's focus on functional behavior: a subsequent collect or put that emits a message.
        // The Log contract stores messages. If LogFile is unchanged (bug), messages go to old Log; if updated (reference), messages go to new Log.
        // We can deploy two Log contracts, set one initially, then call SetLogFile with the second. After a Put, check which Log has the message.
        // However, the test must assert on c's public surface, not on the Log helpers. The assertion must read c.
        // We can read c.LogFile() and compare to what we expect. Let's do that.
        // But since that approach was tried and failed, we need a new angle.
        // The bug is that SetLogFile does not assign the new address. So after calling SetLogFile(x), c.LogFile() still returns the old value.
        // But the compiler error was about LogFile not found. c.LogFile() is the auto-generated getter for public state variable LogFile.
        // The error "Member 'LogFile' not found" in the previous test suggests they tried `c.LogFile()` but it's a state variable of type `Log` (a contract type).
        // The getter for a public state variable of contract type returns that contract type. `address(c.LogFile())` should work.
        // Let's fix by using `address(c.LogFile())` and assert that after SetLogFile(x), the address equals x (for reference) but not for bug.
        // That is exactly the type of property that can be fuzzed.
        // But the instruction says: "Do not repeat: After initialization, calling SetLogFile must update the LogFile state variable; the bug leaves it unchanged."
        // So asserting on LogFile value is prohibited.
        // We need a behavioral difference observable through calls/balance/revert.
        // Since the LogFile is used in Put and Collect to call AddMessage, if LogFile is zero address, the call to zero might succeed but does nothing (no code).
        // If LogFile is a contract that does not have AddMessage, it will revert.
        // Let's set up: Initialize, set LogFile to a valid Log contract, then SetLogFile to a contract that does NOT have AddMessage (adversarial).
        // Adversarial helper: contract NoAddMessage { fallback() external { revert(); } }
        // Deploy NoAddMessage, call SetLogFile with its address.
        // Reference: uses NoAddMessage, Put will try to call AddMessage on it -> fallback -> revert.
        // Bug: ignores SetLogFile, still uses the old valid Log contract -> Put succeeds.
        // Then assert on the revert behavior of Put.
        // That's a perfect behavioral difference triggered by fuzzing the adversarial contract address.
        // Deploy a valid Log helper and a NoAddMessage helper. Fuzz the address of NoAddMessage? No, we deploy it right in the test.
        // The fuzzed parameters can be the lockTime and the actor address pranking.
        vm.assume(lockTime > 0);
        // Deploy a valid Log contract
        Log validLog = new Log();
        // Deploy an adversarial contract that reverts on unknown calls (no AddMessage)
        Reverter noAddMessage = new Reverter();
        // Set up C: SetMinSum to 0, Initialize
        c.SetMinSum(0);
        c.SetLogFile(address(validLog));
        c.Initialized();
        // Now call SetLogFile with the adversarial contract address
        c.SetLogFile(address(noAddMessage));
        // Reference contract will now have LogFile = noAddMessage, so Put will revert.
        // Buggy contract ignores this, still has validLog, so Put will succeed.
        // We need to call Put and observe revert difference.
        address actor = address(0x1234);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        bool ok;
        try c.Put{value: 1}(lockTime) {
            ok = true;
        } catch {
            ok = false;
        }
        // For reference (correct) contract, ok should be false (reverts). For buggy, ok should be true (succeeds).
        // The rule: After SetLogFile to a contract without AddMessage, a subsequent Put MUST revert.
        // Bug violates by not reverting.
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

